SET search_path = public;
CREATE TYPE ad_format AS ENUM ('300x250','336x280','728x90','970x250','320x50','320x100','responsive');
CREATE TYPE ad_load_level AS ENUM ('low','balanced','high');
CREATE TYPE ad_refresh_mode AS ENUM ('none','time_based','scroll_based');
CREATE TYPE ad_report_reason AS ENUM ('inappropriate','misleading','malicious','repetitive','other');
CREATE TYPE ad_report_status AS ENUM ('pending','reviewed','resolved','dismissed');
CREATE TYPE ad_type AS ENUM ('static_image','responsive_display','native','html5');
CREATE TYPE api_key_status AS ENUM ('active','revoked','expired');
CREATE TYPE api_request_status AS ENUM ('success','client_error','server_error','rate_limited');
CREATE TYPE approval_status AS ENUM ('pending','approved','rejected');
CREATE TYPE auto_ads_status AS ENUM ('enabled','disabled');
CREATE TYPE bid_type AS ENUM ('cpm','cpc');
CREATE TYPE billing_event_type AS ENUM ('impression','click');
CREATE TYPE browser_type AS ENUM ('chrome','firefox','safari','edge','opera','other');
CREATE TYPE campaign_objective AS ENUM ('awareness','traffic','engagement','conversions','app_installs');
CREATE TYPE campaign_status AS ENUM ('draft','pending_review','approved','active','paused','completed','rejected');
CREATE TYPE device_type AS ENUM ('desktop','mobile','tablet');
CREATE TYPE earning_status AS ENUM ('pending','available','paid','reversed');
CREATE TYPE entity_status AS ENUM ('active','pending','suspended');
CREATE TYPE health_check_type AS ENUM ('domain_verification','https','privacy_policy','terms_page','ads_txt','website_status','policy_status','ad_placement','traffic_quality');
CREATE TYPE media_status AS ENUM ('pending','ready','rejected','archived');
CREATE TYPE organization_role AS ENUM ('owner','admin','manager','analyst','member');
CREATE TYPE organization_type AS ENUM ('advertiser','publisher','platform');
CREATE TYPE os_type AS ENUM ('windows','macos','linux','android','ios','other');
CREATE TYPE payout_status AS ENUM ('pending','approved','paid','rejected');
CREATE TYPE platform_role AS ENUM ('super_admin','admin','analyst');
CREATE TYPE policy_category AS ENUM ('ad_policies','publisher_guidelines','traffic_quality','prohibited_content','data_privacy','compliance','advertiser_policies','publisher_policies');
CREATE TYPE policy_status AS ENUM ('good','warning','restricted','suspended');
CREATE TYPE storage_provider AS ENUM ('supabase','s3','gcs','cloudflare_r2');
CREATE TYPE verification_method AS ENUM ('dns_txt','meta_tag','html_file');
CREATE TYPE verification_status AS ENUM ('unverified','pending','verified','failed');
CREATE TYPE violation_severity AS ENUM ('low','medium','high','critical');
CREATE TYPE violation_status AS ENUM ('open','in_review','resolved','dismissed');
CREATE TYPE wallet_transaction_type AS ENUM ('deposit','spend','refund','adjustment');
CREATE TYPE website_category AS ENUM ('news','technology','business','finance','entertainment','sports','lifestyle','health','education','travel','gaming','automotive','food','science','other');
CREATE TABLE audit_logs (action text not null, actor_email text default '' not null, actor_id uuid, created_at timestamptz default now() not null, id uuid default gen_random_uuid() primary key, ip_address text, metadata jsonb default '{}' not null, target_id text not null, target_label text, target_type text not null, updated_at timestamptz default now() not null, user_agent text);
CREATE TABLE blocked_ips (blocked_by text, created_at timestamptz default now() not null, expires_at timestamptz, id uuid default gen_random_uuid() primary key, ip_address text not null, reason text not null, updated_at timestamptz default now() not null);
CREATE TABLE fraud_events (actor_id uuid, actor_type text, country text, created_at timestamptz default now() not null, event_type text not null, id uuid default gen_random_uuid() primary key, ip_address text, review_notes text, reviewed_at timestamptz, reviewed_by uuid, score int default 0 not null, severity text default '' not null, signals jsonb default '[]' not null, status text default '' not null, target_id text, target_type text, updated_at timestamptz default now() not null, user_agent text);
CREATE TABLE organizations (created_at timestamptz default now() not null, id uuid default gen_random_uuid() primary key, name text not null, slug text not null unique, status entity_status default 'active' not null, type organization_type not null, updated_at timestamptz default now() not null);
CREATE TABLE payment_providers (active bool default false not null, api_base_url text not null, config jsonb, created_at timestamptz default now() not null, display_name text not null, id uuid default gen_random_uuid() primary key, name text not null unique, supported_countries jsonb default '[]' not null, supported_currencies jsonb default '[]' not null, updated_at timestamptz default now() not null);
CREATE TABLE platform_roles (created_at timestamptz default now() not null, id uuid default gen_random_uuid() primary key, role platform_role not null, updated_at timestamptz default now() not null, user_id uuid not null, unique (user_id, role));
CREATE TABLE platform_settings (assumed_ctr numeric default 0 not null, campaign_minimum_budget numeric default 0 not null, created_at timestamptz default now() not null, currency text default '' not null, default_bid_amount numeric default 0 not null, default_total_budget numeric default 0 not null, earnings_hold_days int default 0 not null, id bool default true primary key, maximum_bid_amount numeric default 0 not null, maximum_campaign_budget numeric default 0 not null, maximum_creative_size_bytes int default 0 not null, maximum_daily_budget numeric default 0 not null, minimum_daily_budget numeric default 0 not null, minimum_payout_amount numeric default 0 not null, platform_status text default '' not null, publisher_revenue_share numeric default 0 not null, starting_cpc numeric default 0 not null, supported_countries text[] default '{}' not null, supported_currencies text[] default '{}' not null, updated_at timestamptz default now() not null);
