CREATE INDEX ON publisher_policies(organization_id);
CREATE TABLE publishers (approval_status approval_status default 'pending' not null, business_name text not null, contact_email text not null, contact_phone text, created_at timestamptz default now() not null, id uuid default gen_random_uuid() primary key, organization_id uuid not null references organizations(id) on delete cascade, rejection_reason text, status entity_status default 'active' not null, updated_at timestamptz default now() not null, website_url text);
