CREATE TABLE rate_limits (action text not null, bucket_key text not null, created_at timestamptz default now() not null, id uuid default gen_random_uuid() primary key, request_count int default 0 not null, updated_at timestamptz default now() not null, window_start text not null, unique (bucket_key, action, window_start));
CREATE TABLE supported_currencies (active bool default false not null, country_code text not null, country_name text not null, created_at timestamptz default now() not null, currency_code text not null, currency_name text not null, decimal_places int default 0 not null, id uuid default gen_random_uuid() primary key, minimum_deposit numeric default 0 not null, symbol text not null, updated_at timestamptz default now() not null, unique (country_code, currency_code));
CREATE TABLE wallets (balance_amount numeric default 0 not null, country_code text default '' not null, created_at timestamptz default now() not null, currency text default '' not null, id uuid default gen_random_uuid() primary key, lifetime_deposited numeric default 0 not null, lifetime_spent numeric default 0 not null, low_balance_threshold numeric default 0 not null, organization_id uuid not null references organizations(id) on delete cascade, updated_at timestamptz default now() not null, unique (organization_id, currency));
CREATE TABLE websites (approval_status approval_status default 'pending' not null, category website_category default 'news' not null, created_at timestamptz default now() not null, description text, domain text not null, id uuid default gen_random_uuid() primary key, monthly_pageviews numeric default 0 not null, name text not null, organization_id uuid not null references organizations(id) on delete cascade, publisher_id uuid not null references publishers(id) on delete cascade, rejection_reason text, status entity_status default 'active' not null, updated_at timestamptz default now() not null, verification_status verification_status default 'unverified' not null, verified_at timestamptz);
CREATE INDEX ON websites(organization_id);
CREATE INDEX ON websites(publisher_id);
