CREATE TABLE publisher_earnings (ad_zone_id uuid references ad_zones(id) on delete cascade, available_at timestamptz default now() not null, campaign_id uuid not null references campaigns(id) on delete cascade, campaign_spend_id uuid not null references campaign_spend(id) on delete cascade, created_at timestamptz default now() not null, event_type billing_event_type not null, gross_amount numeric not null, id uuid default gen_random_uuid() primary key, organization_id uuid not null references organizations(id) on delete cascade, paid_at timestamptz, payout_id uuid references payouts(id) on delete cascade, platform_amount numeric not null, publisher_amount numeric not null, publisher_id uuid not null references publishers(id) on delete cascade, revenue_share numeric not null, status earning_status default 'pending' not null, updated_at timestamptz default now() not null, website_id uuid references websites(id) on delete cascade);
CREATE INDEX ON publisher_earnings(ad_zone_id);
CREATE INDEX ON publisher_earnings(campaign_id);
CREATE UNIQUE INDEX publisher_earnings_spend_unique ON publisher_earnings(campaign_spend_id);
CREATE INDEX ON publisher_earnings(organization_id);
CREATE INDEX ON publisher_earnings(payout_id);
CREATE INDEX ON publisher_earnings(publisher_id);
CREATE INDEX ON publisher_earnings(website_id);
ALTER TABLE ads ADD FOREIGN KEY (logo_media_asset_id) REFERENCES media_assets(id) ON DELETE SET NULL;
ALTER TABLE ads ADD FOREIGN KEY (media_asset_id) REFERENCES media_assets(id) ON DELETE SET NULL;
ALTER TABLE clicks ADD FOREIGN KEY (impression_id) REFERENCES impressions(id) ON DELETE CASCADE;
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
  END LOOP;
END $$;
CREATE POLICY "profiles_select_own" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY "profiles_update_own" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE POLICY "members_select_own" ON public.organization_members FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "platform_roles_select_own" ON public.platform_roles FOR SELECT TO authenticated USING (auth.uid() = user_id);
GRANT SELECT ON public.policies TO anon;
GRANT SELECT ON public.supported_currencies TO anon;
GRANT SELECT ON public.payment_methods TO anon;
GRANT SELECT ON public.payment_providers TO anon;
CREATE POLICY "policies_public_read" ON public.policies FOR SELECT TO anon, authenticated USING (is_published);
CREATE POLICY "currencies_public_read" ON public.supported_currencies FOR SELECT TO anon, authenticated USING (active);
CREATE POLICY "payment_methods_public_read" ON public.payment_methods FOR SELECT TO anon, authenticated USING (active);
CREATE POLICY "payment_providers_public_read" ON public.payment_providers FOR SELECT TO anon, authenticated USING (active);
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid WHERE n.nspname='public' AND c.relkind='r' AND a.attname='updated_at' LOOP
    EXECUTE format('CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_updated_at()', t);
  END LOOP;
END $$;